"""Hacker News — MCP server generated by Handyman.

Tools for reading Hacker News content: individual items (stories, comments, jobs, polls, poll options), user profiles, and curated story-id feeds (top, new, best, Ask HN, Show HN, jobs). To get full details on stories found via a feed tool, call get_item with each id. All data is read-only and public; no authentication is required.

Source API: https://raw.githubusercontent.com/HackerNews/API/master/README.md
Regenerate with: handyman generate https://raw.githubusercontent.com/HackerNews/API/master/README.md --docs --base-url https://hacker-news.firebaseio.com/v0
"""

from typing import Annotated, Any

import httpx
from arcade_mcp_server import MCPApp
from arcade_mcp_server.exceptions import FatalToolError, NetworkTransportError, UpstreamError

app = MCPApp(
    name='hackernews',
    version="0.1.0",
    log_level="ERROR",
    instructions='Tools for reading Hacker News content: individual items (stories, comments, jobs, polls, poll options), user profiles, and curated story-id feeds (top, new, best, Ask HN, Show HN, jobs). To get full details on stories found via a feed tool, call get_item with each id. All data is read-only and public; no authentication is required.',
)

BASE_URL = 'https://hacker-news.firebaseio.com/v0'

# ---------------------------------------------------------------------------
# Request plumbing — the single HTTP door every tool goes through
# ---------------------------------------------------------------------------


def _request(
    method: str,
    path: str,
    params: dict[str, Any] | None = None,
    headers: dict[str, str] | None = None,
) -> Any:
    """Issue one API request and return parsed JSON. Failures are raised as
    Arcade's typed tool errors — a plain exception would be masked as an
    "unhandled error" on the wire, hiding the message from the calling agent."""
    all_headers = dict(_DEFAULT_HEADERS)
    all_headers.update(headers or {})
    try:
        response = httpx.request(
            method,
            BASE_URL + path,
            params=params or None,
            headers=all_headers,
            timeout=30,
            follow_redirects=True,
        )
    except httpx.RequestError as error:
        raise NetworkTransportError(f"{method} {path} did not complete: {error}") from error
    if response.status_code >= 400:
        raise UpstreamError(
            f"{method} {path} failed ({response.status_code}): {response.text[:300]}",
            status_code=response.status_code,
        )
    try:
        return response.json()
    except ValueError as error:
        raise UpstreamError(
            f"{method} {path} returned non-JSON ({response.status_code})",
            status_code=response.status_code,
        ) from error


def _dig(payload: Any, path: str) -> Any:
    """Follow a dot path (numeric segments index lists) into a JSON payload,
    failing loudly when it is absent. Used between chained calls, where a
    missing value means the chain's wiring is wrong — an authoring defect, so
    it raises Arcade's fatal kind rather than an upstream one."""
    value = payload
    for key in path.split("."):
        if isinstance(value, list) and key.isdigit() and int(key) < len(value):
            value = value[int(key)]
        elif isinstance(value, dict) and key in value:
            value = value[key]
        else:
            found = sorted(value.keys()) if isinstance(value, dict) else (
                f"list of {len(value)}" if isinstance(value, list) else type(value).__name__)
            raise FatalToolError(f"response missing '{path}' (at '{key}'; found: {found})")
    return value


def _prune(payload: Any, path: str) -> Any:
    """Best-effort final shaping: return the payload at a dot path (numeric
    segments index lists), or the full payload when the shape drifted — a
    bigger answer beats a broken tool."""
    value = payload
    for key in path.split("."):
        if isinstance(value, list) and key.isdigit() and int(key) < len(value):
            value = value[int(key)]
        elif isinstance(value, dict) and key in value:
            value = value[key]
        else:
            return payload
    return value


def _as_object(value: Any) -> dict:
    """Tools always return a JSON object; non-object payloads are wrapped."""
    return value if isinstance(value, dict) else {"result": value}


_DEFAULT_HEADERS: dict[str, str] = {}


# ---------------------------------------------------------------------------
# Tools
# ---------------------------------------------------------------------------


@app.tool
def get_item(
    id: Annotated[int, "The item's unique numeric id."],
) -> Annotated[dict, 'Object with fields such as id, type, by, time, text, url, title, score, descendants, kids (comment ids), parts (poll option ids), parent, deleted, dead.']:
    """
    Fetch a single Hacker News item (story, comment, job posting, poll, or poll option)
    by its numeric id. Use this to get full details—title, author, text, url, score,
    comment ids, etc.—for an id you already have (e.g. from a feed tool or from a
    story's 'kids'/'parts' list). Returns the item's raw fields, or a null/empty result
    if the id doesn't exist or was deleted.
    """
    response = _request("GET", f"/item/{id}.json")
    return _as_object(response)


@app.tool
def get_user(
    username: Annotated[str, "The user's exact, case-sensitive HN username."],
) -> Annotated[dict, 'Object with id (username), created (unix timestamp), karma, about (bio HTML), and submitted (list of item ids).']:
    """
    Fetch a Hacker News user's public profile by exact, case-sensitive username. Use
    this to check a user's karma, bio, account creation date, or list of submitted item
    ids. Only users with public activity (at least one comment or story) exist; unknown
    usernames return an empty result.
    """
    response = _request("GET", f"/user/{username}.json")
    return _as_object(response)


@app.tool
def get_top_stories(
) -> Annotated[dict, 'Array of up to 500 item ids, ranked from top to bottom.']:
    """
    Get the current front-page 'top stories' on Hacker News (may include jobs) as a list
    of item ids, ordered by current rank. Use this when an agent asks what's trending or
    on the HN front page right now. Follow up with get_item on individual ids to get
    titles/urls/scores. Does not itself return story titles or content.
    """
    response = _request("GET", '/topstories.json')
    return _as_object(response)


@app.tool
def get_new_stories(
) -> Annotated[dict, 'Array of up to 500 item ids, newest first.']:
    """
    Get the most recently submitted stories on Hacker News as a list of item ids, newest
    first. Use this when an agent wants the latest submissions rather than
    ranked/popular ones. Follow up with get_item to fetch details for specific ids.
    """
    response = _request("GET", '/newstories.json')
    return _as_object(response)


@app.tool
def get_best_stories(
) -> Annotated[dict, 'Array of item ids ranked by score.']:
    """
    Get Hacker News' 'best stories' list (stories with the highest recent score,
    distinct from the live front-page ranking) as a list of item ids. Use this for a
    quality/popularity-ranked view rather than pure recency. Follow up with get_item for
    details on specific ids.
    """
    response = _request("GET", '/beststories.json')
    return _as_object(response)


@app.tool
def get_ask_stories(
) -> Annotated[dict, 'Array of up to 200 Ask HN item ids, most recent first.']:
    """
    Get the latest 'Ask HN' discussion posts as a list of item ids. Use this when an
    agent specifically wants Ask HN threads (text-based discussion questions posed to
    the community), not regular link stories. Follow up with get_item for details.
    """
    response = _request("GET", '/askstories.json')
    return _as_object(response)


@app.tool
def get_show_stories(
) -> Annotated[dict, 'Array of up to 200 Show HN item ids, most recent first.']:
    """
    Get the latest 'Show HN' posts (projects/products people are showcasing) as a list
    of item ids. Use this when an agent wants Show HN submissions specifically. Follow
    up with get_item for details.
    """
    response = _request("GET", '/showstories.json')
    return _as_object(response)


@app.tool
def get_job_stories(
) -> Annotated[dict, 'Array of up to 200 job item ids, most recent first.']:
    """
    Get the latest job postings on Hacker News as a list of item ids. Use this when an
    agent asks about HN job listings specifically. Follow up with get_item for details
    such as title and url.
    """
    response = _request("GET", '/jobstories.json')
    return _as_object(response)


if __name__ == "__main__":
    import sys

    app.run(transport=sys.argv[1] if len(sys.argv) > 1 else "stdio")
